const [count, setCount] = useState(0);

const handleAlert = () => {
  setTimeout(() => {
    alert(count);
  }, 3000);
};

return (
  <>
    <p>{count}</p>
    <button onClick={() => setCount(count + 1)}>Increment</button>
    <button onClick={handleAlert}>Show Alert</button>
  </>
);

