function SearchList({ items, query }) {
  const [filteredItems, setFilteredItems] = useState([]);

  useEffect(() => {
    setFilteredItems(items.filter(i => i.includes(query)));
  }, [items, query]);

  return <ul>{filteredItems.map(i => <li key={i}>{i}</li>)}</ul>;
}

